macro_rules! at_rest {
    () => {
        pub (crate) mod at_rest { use bitflags :: bitflags ; bitflags ! { # [doc = " Flags how they are serialized to a storage location"] # [derive (Copy , Clone , Debug)] pub struct Flags : u16 { # [doc = " A portion of a the flags that encodes the length of the path that follows."] const PATH_LEN = 0x0fff ; const STAGE_MASK = 0x3000 ; # [doc = " If set, there is more extended flags past this one"] const EXTENDED = 0x4000 ; # [doc = " If set, the entry be assumed to match with the version on the working tree, as a way to avoid `lstat()`  checks."] const ASSUME_VALID = 0x8000 ; } } impl Flags { pub fn to_memory (self) -> super :: Flags { super :: Flags :: from_bits_retain (u32 :: from (self . bits ())) } } bitflags ! { # [doc = " Extended flags - add flags for serialization here and offset them down to u16."] # [derive (Copy , Clone , Debug , PartialEq)] pub struct FlagsExtended : u16 { const INTENT_TO_ADD = 1 << (29 - 16) ; const SKIP_WORKTREE = 1 << (30 - 16) ; } } impl FlagsExtended { pub fn from_flags (flags : super :: Flags) -> Self { Self :: from_bits_retain (((flags & (super :: Flags :: INTENT_TO_ADD | super :: Flags :: SKIP_WORKTREE)) . bits () >> 16) as u16 ,) } pub fn to_flags (self) -> Option < super :: Flags > { super :: Flags :: from_bits (u32 :: from (self . bits ()) << 16) } } # [cfg (test)] mod tests { use super :: * ; # [test] fn flags_extended_conversion () { assert_eq ! (FlagsExtended :: all () . to_flags () , Some (super :: super :: Flags :: INTENT_TO_ADD | super :: super :: Flags :: SKIP_WORKTREE)) ; assert_eq ! (FlagsExtended :: from_flags (super :: super :: Flags :: all ()) , FlagsExtended :: all ()) ; } # [test] fn flags_from_bits_with_conflict () { let input = 0b1110_0010_1000_1011 ; assert_eq ! (Flags :: from_bits_retain (input) . bits () , input) ; } } }
    };
}

at_rest!();